Here's a C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file:

#include <fstream>
#include <iostream>
#include <string>

int main() {
  std::string wordToCount;    // The word to count
  std::string fileToRead;     // The file name to read
  int counter = 0;             // The counter for the word occurrences

  std::cout << "Enter the word to count: ";
  std::cin >> wordToCount;
  std::cout << "Enter the file name: ";
  std::cin >> fileToRead;

  std::ifstream inputFile(fileToRead);  // Open the file for reading
  if (!inputFile.is_open()) {
    std::cout << "Error opening the file." << std::endl;
    return 1;
  }

  std::string line;
  while (std::getline(inputFile, line)) {  // Read each line
    std::istringstream iss(line);         // Create an input stream from the line
    std::string word;
    while (iss >> word) {                 // Read each word in the line
      if (word == wordToCount) {          // Check if the word matches the one to count
        ++counter;                         // Increment the counter if it's a match
      }
    }
  }

  inputFile.close();                      // Close the file

  std::cout << wordToCount << " occurs " << counter << " times in the file." << std::endl;

  return 0;                                // Indicate successful execution
